const bookingId = "55555555-5555-4555-8555-555555555555";
const previousCleanerId = "44444444-4444-4444-8444-444444444444";
const previousPropertyId = "33333333-3333-4333-8333-333333333333";
const testNow = Date.parse("2026-07-18T12:00:00.000Z");
const common = { bookingId, scheduledStartAt: "2026-07-20T09:00:00.000Z", scheduledEndAt: "2026-07-20T12:00:00.000Z", responseDeadline: "2026-07-18T14:00:00.000Z", pricePence: 7500, propertyArea: "SW1A", taskCount: 4 };
const cleanerRecords = [
  { ...common, participantRole: "cleaner", status: "pending-cleaner-acceptance", canRespond: true },
  { ...common, bookingId: "66666666-6666-4666-8666-666666666666", participantRole: "cleaner", status: "cleaning-in-progress", activeJobAvailable: true },
  { ...common, bookingId: "77777777-7777-4777-8777-777777777777", participantRole: "cleaner", status: "completed", activeJobAvailable: true }
];
const landlordRecords = [{ ...common, participantRole: "landlord", status: "confirmed", pricePence: 12000, paymentStepAvailable: true, activeJobAvailable: true }];
const cleanerBuckets = bookingSummaryBuckets(cleanerRecords, "cleaner", testNow);
const landlordBuckets = bookingSummaryBuckets(landlordRecords, "landlord");
assert(cleanerBuckets.pending.length === 1 && cleanerBuckets.active.length === 1 && cleanerBuckets.history.length === 1, "Cleaner bookings were grouped into the wrong dashboard sections.");
assert(landlordBuckets.upcoming.length === 1 && landlordBuckets.pending.length === 0, "Landlord bookings were grouped into the wrong dashboard sections.");
assert(dashboardWorkspaceAccess({ selectedRole: "landlord", roles: ["landlord"] }, "landlord").ready === true, "A Landlord account was denied its dedicated dashboard.");
assert(accountWorkspaceDestination({ selectedRole: "cleaner", roles: ["cleaner"] }, "work") === "/cleaner/onboarding", "A Work as a Cleaner intent does not continue into dedicated onboarding.");
assert(accountWorkspaceDestination({ selectedRole: "landlord", roles: ["landlord", "cleaner"] }, "work") === "/cleaner/onboarding", "A multi-workspace Work as a Cleaner intent does not open dedicated onboarding.");
assert(accountWorkspaceDestination({ selectedRole: "cleaner", roles: ["cleaner"] }) === "/cleaner/dashboard", "A normal Cleaner login does not preserve the operational dashboard.");
assert(accountIntentWorkspaceActivation({ selectedRole: "landlord", roles: ["landlord", "cleaner"] }, "work") === "cleaner", "A Cleaner sign-in intent cannot identify the required active-workspace change.");
assert(accountIntentWorkspaceActivation({ selectedRole: "cleaner", roles: ["landlord", "cleaner"] }, "work") === "", "An already-active Cleaner workspace is needlessly rotated.");
assert(accountIntentWorkspaceActivation({ selectedRole: "landlord", roles: ["landlord"] }, "work") === "", "A Landlord-only account can silently grant itself the Cleaner role without explicit onboarding.");
assert(accountWorkspaceDestination({ selectedRole: "cleaner", roles: ["cleaner"] }, "work", false) === "/account-ready", "A Cleaner sign-in intent can bypass the marketplace readiness handoff.");
assert(accountWorkspaceDestination({ selectedRole: "landlord", roles: ["landlord"] }, "book") === "/landlord/book", "A Landlord booking intent no longer continues directly into the booking journey.");
assert(accountWorkspaceDestination({ selectedRole: "cleaner", roles: ["cleaner"] }, "book") === "", "A Cleaner-only account can enter the Landlord booking journey without adding the Landlord workspace.");
const cleanerBoundary = dashboardWorkspaceAccess({ selectedRole: "landlord", roles: ["landlord", "cleaner"] }, "cleaner");
assert(cleanerBoundary.ready === false && cleanerBoundary.reason === "different-workspace" && cleanerBoundary.destination === "/landlord/dashboard", "A multi-workspace account can still mix its active Landlord and Cleaner dashboards.");
assert(dashboardWorkspaceAccess({ selectedRole: "landlord", roles: ["landlord"] }, "cleaner").reason === "role-missing", "A Landlord-only account was treated as a Cleaner account.");
assert(trustedAccountPhoto("https://lh3.googleusercontent.com/a/photo") && trustedAccountPhoto("https://platform-lookaside.fbsbx.com/platform/profilepic/") && trustedAccountPhoto("https://scontent-lhr8-2.xx.fbcdn.net/photo.jpg"), "Trusted Google or Facebook account photos were rejected.");
assert(trustedAccountPhoto("https://attacker.example/avatar.jpg") === "" && trustedAccountPhoto("http://lh3.googleusercontent.com/avatar.jpg") === "", "An arbitrary or insecure remote account photo can still load inside a private dashboard.");
const landlordOverview = landlordDashboardSummary([
  { ...landlordRecords[0], status: "completed", counterpartyName: "Alex Cleaner", bookingId: "11111111-1111-4111-8111-111111111111", pricePence: 7500, scheduledStartAt: "2026-07-10T09:00:00.000Z" },
  { ...landlordRecords[0], status: "completed", counterpartyName: "Alex Cleaner", bookingId: "22222222-2222-4222-8222-222222222222", cleanerId: previousCleanerId, propertyId: previousPropertyId, pricePence: 8000, scheduledStartAt: "2026-07-12T09:00:00.000Z" },
  { ...landlordRecords[0], status: "awaiting-review", counterpartyName: "Sam Cleaner", bookingId: "33333333-3333-4333-8333-333333333333", pricePence: 9000 }
]);
assert(landlordOverview.completedCleanCount === 2 && landlordOverview.awaitingConfirmationCount === 1 && landlordOverview.completedBookingValuePence === 15500 && landlordOverview.previousCleanerVisitCount === 2, "The Landlord history summary calculated the wrong private account totals.");
assert(landlordOverview.previousCleanerVisits[0].displayName === "Alex Cleaner" && landlordOverview.previousCleanerVisits[0].bookingId === "22222222-2222-4222-8222-222222222222", "The Landlord history summary did not preserve the latest completed Cleaner visit safely.");
